async (page) => {
  const email = 'explore'+Date.now()+'@example.test';
  const ctx = page.context();
  await ctx.addCookies([{name:'cookieconsent_status', value:'dismiss', url:'http://localhost:3000'}]);
  const req = page.request;
  await req.post('/api/Users', {data:{email,password:'Passw0rd!x',passwordRepeat:'Passw0rd!x',securityQuestion:{id:1},securityAnswer:'x'}});
  await page.goto('http://localhost:3000/#/login');
  await page.getByLabel('Text field for the login email').fill(email);
  await page.getByLabel('Text field for the login password').fill('Passw0rd!x');
  await page.getByRole('button', {name: 'Login', exact: true}).click();
  await page.waitForURL(/search/);
  const tok = await page.evaluate(() => localStorage.getItem('token'));
  return email + ' ' + await page.evaluate(() => JSON.stringify({ls: {...localStorage}, ss: {...sessionStorage}, c: document.cookie}));
}

