/** Money math in whole cents, to avoid floating point errors in expected values. */
export const toCents = (amount: number): number => Math.round(amount * 100);

export const fromCents = (cents: number): number => cents / 100;

/** Formats an amount the way the shop shows prices: `8.99¤`. */
export const price = (amount: number): string => `${amount.toFixed(2)}¤`;

export interface Line {
  price: number;
  quantity: number;
}

export const itemsTotal = (lines: Line[]): number =>
  fromCents(lines.reduce((sum, l) => sum + toCents(l.price) * l.quantity, 0));

export const itemCount = (lines: Line[]): number => lines.reduce((sum, l) => sum + l.quantity, 0);

/** Discount on the price of the products only, rounded to cents. */
export const discount = (items: number, percent: number): number =>
  fromCents(Math.round((toCents(items) * percent) / 100));

export const orderTotal = (items: number, delivery: number, promotion = 0): number =>
  fromCents(toCents(items) + toCents(delivery) - toCents(promotion));

/** Bonus points of an order: round(product price / 10) × quantity, per product. */
export const bonusPoints = (lines: Line[]): number =>
  lines.reduce((sum, l) => sum + Math.round(l.price / 10) * l.quantity, 0);

