import type { APIRequestContext } from '@playwright/test';
import * as z85 from 'z85';

const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];

/** Coupon code for the month of `date`: Z85 of `<MMM><YY>-<NN>`. */
export function couponCode(date: Date, discountPercent: number): string {
  const month = MONTHS[date.getUTCMonth()];
  const year = String(date.getUTCFullYear() % 100).padStart(2, '0');
  const percent = String(discountPercent).padStart(2, '0');
  const code = z85.encode(`${month}${year}-${percent}`);
  if (!code) throw new Error(`Cannot encode coupon for ${date.toISOString()}`);
  return code;
}

/** The date of the machine that runs the app, from the HTTP `Date` header. */
export async function appDate(request: APIRequestContext): Promise<Date> {
  const response = await request.get('/rest/admin/application-version');
  const header = response.headers()['date'];
  return header ? new Date(header) : new Date();
}

export function previousMonth(date: Date): Date {
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() - 1, 15));
}

