import type { Locator, Page } from '@playwright/test';

/** Top bar of the shop: account menu and basket button. */
export class NavBar {
  readonly accountButton: Locator;
  readonly basketButton: Locator;
  readonly basketCounter: Locator;
  readonly accountMenu: Locator;
  readonly loginMenuItem: Locator;
  readonly logoutMenuItem: Locator;
  readonly profileMenuItem: Locator;
  readonly ordersAndPaymentMenuItem: Locator;
  readonly orderHistoryMenuItem: Locator;
  readonly digitalWalletMenuItem: Locator;

  constructor(private readonly page: Page) {
    this.accountButton = page.getByRole('button', { name: 'Show/hide account menu' });
    this.basketButton = page.getByRole('button', { name: 'Show the shopping cart' });
    this.basketCounter = this.basketButton.locator('.fa-layers-counter');
    this.accountMenu = page.locator('.mat-mdc-menu-panel').first();
    this.loginMenuItem = page.getByRole('menuitem', { name: 'Go to login page' });
    this.logoutMenuItem = page.getByRole('menuitem', { name: 'Logout' });
    this.profileMenuItem = page.getByRole('menuitem', { name: 'Go to user profile' });
    this.ordersAndPaymentMenuItem = page.getByRole('menuitem', { name: 'Show Orders and Payment Menu' });
    this.orderHistoryMenuItem = page.getByRole('menuitem', { name: 'Go to order history page' });
    this.digitalWalletMenuItem = page.getByRole('menuitem', { name: 'Go to wallet page' });
  }

  async openAccountMenu(): Promise<void> {
    await this.accountButton.click();
  }

