/** Product list `/#/search`. */
export class SearchPage {
  readonly snackBar: Locator;

  constructor(private readonly page: Page) {
    this.snackBar = page.locator('.mat-mdc-snack-bar-label');
  }

  async goto(): Promise<void> {
    await this.page.goto('/#/search');
  }

  productCard(name: string): Locator {
    return this.page.locator('mat-grid-tile mat-card').filter({ hasText: name });
  }

  productName(name: string): Locator {
    return this.productCard(name).locator('.item-name');
  }

  productPrice(name: string): Locator {
    return this.productCard(name).locator('.item-price');
  }

  addToBasketButton(name: string): Locator {
    return this.productCard(name).getByRole('button', { name: 'Add to Basket' });
  }

  async addToBasket(name: string): Promise<void> {
    await this.addToBasketButton(name).click();
  }

  /** Closes all open messages, so that the next message can be read alone. */
  async dismissMessages(): Promise<void> {
    await this.page.locator('.mat-mdc-snack-bar-container').evaluateAll((els) => els.forEach((e) => e.remove()));
  }
}

