import type { Locator, Page } from '@playwright/test';
import { BasketTable } from './BasketPage';

/** `/#/address/select` */
export class AddressSelectPage {
  readonly title: Locator;
  readonly rows: Locator;
  readonly continueButton: Locator;

  constructor(page: Page) {
    const root = page.locator('app-address-select');
    this.title = root.getByRole('heading', { name: 'Select an address' });
    this.rows = root.locator('mat-row');
    this.continueButton = page.getByRole('button', { name: 'Proceed to payment selection' });
  }

  address(fullName: string): Locator {
    return this.rows.filter({ hasText: fullName });
  }

  async selectAndContinue(fullName: string): Promise<void> {
    await this.address(fullName).locator('mat-radio-button').click();
    await this.continueButton.click();
  }
}

/** `/#/delivery-method` */
export class DeliveryMethodPage {
  readonly title: Locator;
  readonly continueButton: Locator;

  constructor(private readonly page: Page) {
    this.title = page.locator('app-delivery-method').getByRole('heading', { name: 'Choose a delivery speed' });
    this.continueButton = page.getByRole('button', { name: 'Proceed to delivery method selection' });
  }

  method(name: string): Locator {
    return this.page.locator('app-delivery-method mat-row').filter({ hasText: name });
  }

  price(name: string): Locator {
    return this.method(name).locator('mat-cell').nth(2);
  }

  async selectAndContinue(name: string): Promise<void> {
    await this.method(name).locator('mat-radio-button').click();
    await this.continueButton.click();
  }
}

/** `/#/payment/shop` */
export class PaymentPage {
  readonly title: Locator;
  readonly cards: Locator;
  readonly walletBalance: Locator;
  readonly payWithWalletButton: Locator;
  readonly couponPanel: Locator;
  readonly couponPanelHeader: Locator;
  readonly couponInput: Locator;
  readonly redeemButton: Locator;
  readonly couponError: Locator;
  readonly couponConfirmation: Locator;
  readonly continueButton: Locator;

  constructor(page: Page) {
    const root = page.locator('app-payment');
    this.title = root.getByRole('heading', { name: 'My Payment Options' });
    this.cards = root.locator('app-payment-method mat-row');
    this.walletBalance = root.locator('span', { hasText: 'Wallet Balance' }).locator('xpath=following-sibling::span');
    this.payWithWalletButton = root.getByRole('button', { name: /^Pay / });
    this.couponPanel = root.locator('#collapseCouponElement');
    this.couponPanelHeader = this.couponPanel.locator('mat-expansion-panel-header');
    this.couponInput = root.locator('#coupon');
    this.redeemButton = root.locator('#applyCouponButton');
    this.couponError = this.couponPanel.locator('.error');
    this.couponConfirmation = this.couponPanel.locator('.confirmation');
    this.continueButton = page.getByRole('button', { name: 'Proceed to review' });
  }

  card(lastDigits: string): Locator {
    return this.cards.filter({ hasText: `************${lastDigits}` });
  }

  async openCouponPanel(): Promise<void> {
    if ((await this.couponPanelHeader.getAttribute('aria-expanded')) !== 'true') {
      await this.couponPanelHeader.click();
    }
  }

  async redeemCoupon(code: string): Promise<void> {
    await this.couponInput.fill(code);
    await this.redeemButton.click();
  }

  async selectCardAndContinue(lastDigits: string): Promise<void> {
    await this.card(lastDigits).locator('mat-radio-button').click();
    await this.continueButton.click();
  }
}

/** Summary table with the rows Items, Delivery, Promotion, Total Price. */
function summaryValue(table: Locator, label: string): Locator {
  return table.locator('tr').filter({ has: table.page().locator('td', { hasText: new RegExp(`^\\s*${label}\\s*$`) }) }).locator('td').nth(1);
}

/** `/#/order-summary` */
export class OrderSummaryPage {
  readonly root: Locator;
  readonly basket: BasketTable;
  readonly deliveryAddress: Locator;
  readonly paymentMethod: Locator;
  readonly items: Locator;
  readonly delivery: Locator;
  readonly promotion: Locator;
  readonly totalPrice: Locator;
  readonly placeOrderButton: Locator;

  constructor(page: Page) {
    this.root = page.locator('app-order-summary');
    this.basket = new BasketTable(this.root);
    this.deliveryAddress = this.root.locator('mat-card', { hasText: 'Delivery Address' }).last();
    this.paymentMethod = this.root.locator('mat-card', { hasText: 'Payment Method' }).last();
    const summary = this.root.locator('table');
    this.items = summaryValue(summary, 'Items');
    this.delivery = summaryValue(summary, 'Delivery');
    this.promotion = summaryValue(summary, 'Promotion');
    this.totalPrice = summaryValue(summary, 'Total Price');
    this.placeOrderButton = page.getByRole('button', { name: 'Complete your purchase' });
  }
}

/** `/#/order-completion/<order ID>` */
export class OrderCompletionPage {
  readonly root: Locator;
  readonly confirmation: Locator;
  readonly rows: Locator;
  readonly items: Locator;
  readonly delivery: Locator;
  readonly promotion: Locator;
  readonly totalPrice: Locator;

  constructor(private readonly page: Page) {
    this.root = page.locator('app-order-completion');
    this.confirmation = this.root.getByRole('heading', { name: 'Thank you for your purchase!' });
    this.rows = this.root.locator('mat-row');
    // The footer holds two tables: the labels and the values, in the same order.
    const values = this.root.locator('mat-footer-row mat-footer-cell').nth(3).locator('td');
    this.items = values.nth(0);
    this.delivery = values.nth(1);
    this.promotion = values.nth(2);
    this.totalPrice = values.nth(3);
  }

  row(productName: string): Locator {
    return this.rows.filter({ hasText: productName });
  }

  quantity(productName: string): Locator {
    return this.row(productName).locator('mat-cell').nth(2);
  }

  orderId(): string {
    const match = this.page.url().match(/order-completion\/([^/?#]+)/);
    if (!match) throw new Error(`No order ID in URL ${this.page.url()}`);
    return match[1];
  }
}

