      await expect(navBar.basketCounter).toHaveText('0');
    });

    await test.step('2. Add the product to the basket', async () => {
      await searchPage.addToBasket(product.name);
      await expect(searchPage.snackBar).toHaveText(`Placed ${product.name} into basket.`);
      await expect(navBar.basketCounter).toHaveText('1');
    });

    await test.step('3. Open the basket', async () => {
      await navBar.openBasket();
      await expect(page).toHaveURL(/#\/basket/);
      await expect(basketPage.table.rows).toHaveCount(1);
      await expect(basketPage.table.row(product.name)).toBeVisible();
      await expect(basketPage.table.quantity(product.name)).toHaveText('1');
      await expect(basketPage.table.price(product.name)).toHaveText(price(product.price));
    });

    await test.step('4. Read the total of the basket', async () => {
      await expect(basketPage.totalPrice).toHaveText(`Total Price: ${price(product.price)}`);
    });
  });
});

