import { test, expect } from './fixtures';
import { PRODUCTS, PURCHASE_LIMIT } from '../data/test-data';
import { itemsTotal, price } from '../helpers/money';

test.describe('TC-04: Purchase limit for one product', () => {
  test('TC-04 basket holds at most the limit of a limited product', async ({
    loginAsCustomer,
    searchPage,
    basketPage,
    navBar,
  }) => {
    const product = PRODUCTS.appleJuice;
    const limitMessage = `You can order only up to ${PURCHASE_LIMIT} items of this product.`;
    const totalFor = (quantity: number) => `Total Price: ${price(itemsTotal([{ price: product.price, quantity }]))}`;
    await loginAsCustomer();

    await test.step('1. Add the product from the product list', async () => {
      await searchPage.goto();
      await searchPage.addToBasket(product.name);
      await expect(searchPage.snackBar).toHaveText(`Placed ${product.name} into basket.`);
      await expect(navBar.basketCounter).toHaveText('1');
    });

    await test.step(`2. Click plus until the quantity is ${PURCHASE_LIMIT}`, async () => {
      await basketPage.goto();
      for (let quantity = 2; quantity <= PURCHASE_LIMIT; quantity++) {
        await basketPage.plusButton(product.name).click();
        await expect(basketPage.table.quantity(product.name)).toHaveText(String(quantity));
      }
      await expect(basketPage.totalPrice).toHaveText(totalFor(PURCHASE_LIMIT));
      await expect(basketPage.snackBar).toHaveCount(0);
    });

    await test.step('3. Click plus one more time', async () => {
      await basketPage.plusButton(product.name).click();
      await expect(basketPage.snackBar).toHaveText(limitMessage);
    });

    await test.step('4. Read the basket', async () => {
      await expect(basketPage.table.quantity(product.name)).toHaveText(String(PURCHASE_LIMIT));
      await expect(basketPage.totalPrice).toHaveText(totalFor(PURCHASE_LIMIT));
      await expect(navBar.basketCounter).toHaveText(String(PURCHASE_LIMIT));
    });

    await test.step('5. Add the product again from the product list', async () => {
      await searchPage.goto();
      await searchPage.dismissMessages();
      await searchPage.addToBasket(product.name);
      await expect(searchPage.snackBar).toHaveText(limitMessage);
      await expect(navBar.basketCounter).toHaveText(String(PURCHASE_LIMIT));
    });
  });
});

