import { test, expect } from './fixtures';
import { ADDRESS, CARD, CARD_LAST_DIGITS, DELIVERY, PRODUCTS } from '../data/test-data';
import { appDate, couponCode } from '../helpers/coupon';
import { discount, itemCount, itemsTotal, orderTotal, price } from '../helpers/money';

const COUPON_DISCOUNT = 10;

test.describe('TC-07: Order with a card, from basket to order history', () => {
  test('TC-07 card order with a coupon reaches the order history', async ({
    page,
    request,
    api,
    loginAsCustomer,
    navBar,
    searchPage,
    basketPage,
    addressPage,
    deliveryPage,
    paymentPage,
    orderSummaryPage,
    orderCompletionPage,
    orderHistoryPage,
  }) => {
    const a = PRODUCTS.eggfruitJuice;
    const b = PRODUCTS.carrotJuice;
    const qtyA = 2;
    const qtyB = 1;
    const lines = [
      { price: a.price, quantity: qtyA },
      { price: b.price, quantity: qtyB },
    ];
    const delivery = DELIVERY.oneDay;
    const coupon = couponCode(await appDate(request), COUPON_DISCOUNT);
    const items = itemsTotal(lines);
    const promotion = discount(items, COUPON_DISCOUNT);
    const total = orderTotal(items, delivery.price, promotion);
    let orderId = '';

    await api.addAddress();
    await api.addCard();
    await loginAsCustomer();

    await test.step('1. Add the products from the product list', async () => {
      await searchPage.goto();
      for (let i = 1; i <= qtyA; i++) {
        await searchPage.addToBasket(a.name);
        await expect(navBar.basketCounter).toHaveText(String(i));
      }
      await searchPage.addToBasket(b.name);
      await expect(navBar.basketCounter).toHaveText(String(itemCount(lines)));
    });

    await test.step('2. Open the basket', async () => {
      await basketPage.goto();
      await expect(basketPage.table.rows).toHaveCount(2);
      await expect(basketPage.table.quantity(a.name)).toHaveText(String(qtyA));
      await expect(basketPage.table.quantity(b.name)).toHaveText(String(qtyB));
      await expect(basketPage.totalPrice).toHaveText(`Total Price: ${price(items)}`);
    });

    await test.step('3. Checkout and select the saved address', async () => {
      await basketPage.checkout();
      await addressPage.selectAndContinue(ADDRESS.fullName);
      await expect(deliveryPage.title).toBeVisible();
    });

    await test.step(`4. Select ${delivery.name} and continue`, async () => {
      await deliveryPage.selectAndContinue(delivery.name);
      await expect(paymentPage.title).toBeVisible();
    });

    await test.step('5. Redeem the coupon of the current month', async () => {
      await paymentPage.openCouponPanel();
      await paymentPage.redeemCoupon(coupon);
      await expect(paymentPage.couponConfirmation).toHaveText(
        `Your discount of ${COUPON_DISCOUNT}% will be applied during checkout.`,
      );
    });

    await test.step('6. Select the saved card and continue', async () => {
      await paymentPage.selectCardAndContinue(CARD_LAST_DIGITS);
      await expect(page).toHaveURL(/#\/order-summary/);
      await expect(orderSummaryPage.deliveryAddress).toContainText(ADDRESS.fullName);
      await expect(orderSummaryPage.deliveryAddress).toContainText(
        `${ADDRESS.streetAddress}, ${ADDRESS.city}, ${ADDRESS.state}, ${ADDRESS.zipCode}`,
      );
      await expect(orderSummaryPage.deliveryAddress).toContainText(ADDRESS.country);
      await expect(orderSummaryPage.paymentMethod).toContainText(`Card ending in ${CARD_LAST_DIGITS}`);
      await expect(orderSummaryPage.paymentMethod).toContainText(CARD.fullName);
      await expect(orderSummaryPage.items).toHaveText(price(items));
      await expect(orderSummaryPage.delivery).toHaveText(price(delivery.price));
      await expect(orderSummaryPage.promotion).toHaveText(price(promotion));
      await expect(orderSummaryPage.totalPrice).toHaveText(price(total));
    });

    await test.step('7. Place the order', async () => {
      await orderSummaryPage.placeOrderButton.click();
      await expect(page).toHaveURL(/#\/order-completion\/[^/]+$/);
      await expect(orderCompletionPage.confirmation).toBeVisible();
      orderId = orderCompletionPage.orderId();
    });

    await test.step('8. Read the order summary on the confirmation page', async () => {
      await expect(orderCompletionPage.rows).toHaveCount(2);
