import { test, expect } from './fixtures';
import { ADDRESS, DELIVERY, PRODUCTS } from '../data/test-data';
import { bonusPoints, fromCents, itemsTotal, orderTotal, price, toCents } from '../helpers/money';

const FIRST_BALANCE = 5;
const TOP_UP = 3.99;

test.describe('TC-08: Payment with the wallet', () => {
  test('TC-08 wallet pays only when it holds the order total', async ({
    page,
    api,
    loginAsCustomer,
    navBar,
    basketPage,
    addressPage,
    deliveryPage,
    paymentPage,
    orderSummaryPage,
    orderCompletionPage,
    orderHistoryPage,
    walletPage,
  }) => {
    const product = PRODUCTS.eggfruitJuice;
    const lines = [{ price: product.price, quantity: 1 }];
    const delivery = DELIVERY.standard;
    const total = orderTotal(itemsTotal(lines), delivery.price);
    const bonus = bonusPoints(lines);
    const balanceBeforeOrder = fromCents(toCents(FIRST_BALANCE) + toCents(TOP_UP));
    const balanceAfterOrder = fromCents(toCents(balanceBeforeOrder) - toCents(total) + toCents(bonus));

    await api.addAddress();
    const cardId = await api.addCard();
    await api.addToBasket(product.id, 1);
    expect(await api.walletBalance()).toBe(0);
    expect(await api.topUpWallet(FIRST_BALANCE, cardId)).toBe(FIRST_BALANCE);
    await loginAsCustomer();

    const checkoutToPayment = async () => {
      await basketPage.goto();
      await basketPage.checkout();
      await addressPage.selectAndContinue(ADDRESS.fullName);
      await expect(deliveryPage.title).toBeVisible();
    };

    // Part 1: the wallet holds less than the order total.

    await test.step('1. Checkout and select the saved address', async () => {
      await checkoutToPayment();
    });

    await test.step(`2. Select ${delivery.name} and continue`, async () => {
      await deliveryPage.selectAndContinue(delivery.name);
      await expect(paymentPage.title).toBeVisible();
      await expect(paymentPage.walletBalance).toHaveText(FIRST_BALANCE.toFixed(2));
      await expect(paymentPage.payWithWalletButton).toHaveText(`Pay ${price(total)}`);
    });

    await test.step(`3. The button Pay ${price(total)} is disabled`, async () => {
      await expect(paymentPage.payWithWalletButton).toBeDisabled();
    });

    await test.step('4. The order history is empty', async () => {
      await navBar.openOrderHistory();
      await expect(page).toHaveURL(/#\/order-history/);
      await expect(orderHistoryPage.root).toContainText('No orders placed yet.');
      await expect(orderHistoryPage.orders).toHaveCount(0);
    });

    await test.step('5. The wallet balance is unchanged', async () => {
      await navBar.openDigitalWallet();
      await expect(page).toHaveURL(/#\/wallet/);
      await expect(walletPage.balance).toHaveText(FIRST_BALANCE.toFixed(2));
    });

    // Part 2: the wallet holds exactly the order total.

    await test.step(`Top up the wallet with ${TOP_UP} from the saved card`, async () => {
      expect(await api.topUpWallet(TOP_UP, cardId)).toBeCloseTo(balanceBeforeOrder, 2);
    });

    await test.step('6. Checkout to the payment step again', async () => {
      await checkoutToPayment();
      await deliveryPage.selectAndContinue(delivery.name);
      await expect(paymentPage.title).toBeVisible();
      await expect(paymentPage.walletBalance).toHaveText(balanceBeforeOrder.toFixed(2));
      await expect(paymentPage.payWithWalletButton).toHaveText(`Pay ${price(total)}`);
      await expect(paymentPage.payWithWalletButton).toBeEnabled();
    });

    await test.step(`7. Click Pay ${price(total)}`, async () => {
      await paymentPage.payWithWalletButton.click();
      await expect(page).toHaveURL(/#\/order-summary/);
      await expect(orderSummaryPage.paymentMethod).toContainText('Digital Wallet');
      await expect(orderSummaryPage.totalPrice).toHaveText(price(total));
    });

    await test.step('8. Place the order', async () => {
      await orderSummaryPage.placeOrderButton.click();
      await expect(page).toHaveURL(/#\/order-completion\/[^/]+$/);
      await expect(orderCompletionPage.confirmation).toBeVisible();
    });

    await test.step('9. The wallet balance is the rest plus the bonus', async () => {
      await navBar.openDigitalWallet();
      await expect(page).toHaveURL(/#\/wallet/);
      await expect(walletPage.balance).toHaveText(balanceAfterOrder.toFixed(2));
    });

    await test.step('10. The order history shows the order', async () => {
      await navBar.openOrderHistory();
      await expect(page).toHaveURL(/#\/order-history/);
      await expect(orderHistoryPage.orders).toHaveCount(1);
      const order = orderHistoryPage.nth(0);
      await expect(order.totalPrice).toHaveText(price(total));
      await expect(order.bonus).toHaveText(String(bonus));
    });
  });
});

