import { test as base, expect } from '@playwright/test';
import { registerCustomer, ShopApi, type Customer } from '../helpers/api';
import { LoginPage } from '../pages/LoginPage';
import { NavBar } from '../pages/NavBar';
import { SearchPage } from '../pages/SearchPage';
import { BasketPage } from '../pages/BasketPage';
import {
  AddressSelectPage,
  DeliveryMethodPage,
  OrderCompletionPage,
  OrderSummaryPage,
  PaymentPage,
} from '../pages/CheckoutPages';
import { OrderHistoryPage, WalletPage } from '../pages/AccountPages';

interface Pages {
  loginPage: LoginPage;
  navBar: NavBar;
  searchPage: SearchPage;
  basketPage: BasketPage;
  addressPage: AddressSelectPage;
  deliveryPage: DeliveryMethodPage;
  paymentPage: PaymentPage;
  orderSummaryPage: OrderSummaryPage;
  orderCompletionPage: OrderCompletionPage;
  orderHistoryPage: OrderHistoryPage;
  walletPage: WalletPage;
}

interface Fixtures extends Pages {
  /** A new customer account, unique for each test. */
  customer: Customer;
  /** REST API of the customer, to prepare preconditions. */
  api: ShopApi;
  /** Logs the customer in through the login page and waits for the product list. */
  loginAsCustomer: () => Promise<void>;
}

export const test = base.extend<Fixtures>({
  page: async ({ page, context, baseURL }, use) => {
    // Hide the cookie banner.
    await context.addCookies([{ name: 'cookieconsent_status', value: 'dismiss', url: baseURL! }]);
    await use(page);
  },
  customer: async ({ request }, use, testInfo) => {
    const prefix = testInfo.titlePath.find((t) => /^TC-\d+/.test(t))?.slice(0, 5).toLowerCase() ?? 'test';
    await use(await registerCustomer(request, prefix));
  },
  api: async ({ request, customer }, use) => {
    await use(await ShopApi.login(request, customer));
  },
  loginAsCustomer: async ({ page, customer }, use) => {
    await use(async () => {
      const loginPage = new LoginPage(page);
      await loginPage.goto();
      await loginPage.login(customer.email, customer.password);
      await expect(page).toHaveURL(/#\/search/);
    });
  },
  loginPage: async ({ page }, use) => use(new LoginPage(page)),
  navBar: async ({ page }, use) => use(new NavBar(page)),
  searchPage: async ({ page }, use) => use(new SearchPage(page)),
  basketPage: async ({ page }, use) => use(new BasketPage(page)),
  addressPage: async ({ page }, use) => use(new AddressSelectPage(page)),
  deliveryPage: async ({ page }, use) => use(new DeliveryMethodPage(page)),
  paymentPage: async ({ page }, use) => use(new PaymentPage(page)),
  orderSummaryPage: async ({ page }, use) => use(new OrderSummaryPage(page)),
  orderCompletionPage: async ({ page }, use) => use(new OrderCompletionPage(page)),
  orderHistoryPage: async ({ page }, use) => use(new OrderHistoryPage(page)),
  walletPage: async ({ page }, use) => use(new WalletPage(page)),
});

export { expect };

