import type { Locator, Page } from '@playwright/test';

/** Basket table, used on `/#/basket` and in the order summary. */
export class BasketTable {
  readonly rows: Locator;

  constructor(root: Locator) {
    this.rows = root.locator('app-purchase-basket mat-row');
  }

  row(productName: string): Locator {
    return this.rows.filter({ hasText: productName });
  }

  /** Quantity cell (column 3). */
  quantity(productName: string): Locator {
    return this.row(productName).locator('mat-cell').nth(2);
  }

  /** Price cell (column 4). */
  price(productName: string): Locator {
    return this.row(productName).locator('mat-cell').nth(3);
  }
}

export class BasketPage {
  readonly table: BasketTable;
  readonly totalPrice: Locator;
  readonly checkoutButton: Locator;
  readonly snackBar: Locator;

  constructor(private readonly page: Page) {
    const root = page.locator('app-basket');
    this.table = new BasketTable(root);
    this.totalPrice = root.locator('#price');
    this.checkoutButton = root.locator('#checkoutButton');
    this.snackBar = page.locator('.mat-mdc-snack-bar-label');
  }

  async goto(): Promise<void> {
    await this.page.goto('/#/basket');
  }

  plusButton(productName: string): Locator {
    return this.table.row(productName).locator('button:has(svg[data-icon="plus-square"])');
  }

  minusButton(productName: string): Locator {
    return this.table.row(productName).locator('button:has(svg[data-icon="minus-square"])');
  }

  trashButton(productName: string): Locator {
    return this.table.row(productName).locator('button:has(svg[data-icon="trash-alt"])');
  }

  async checkout(): Promise<void> {
    await this.checkoutButton.click();
  }
}

