import { expect, type APIRequestContext } from '@playwright/test';
import { ADDRESS, CARD } from '../data/test-data';

export interface Customer {
  email: string;
  password: string;
}

export interface Session {
  token: string;
  basketId: number;
}

/** Creates a unique customer account through the REST API. */
export async function registerCustomer(request: APIRequestContext, prefix: string): Promise<Customer> {
  const unique = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const customer = { email: `${prefix}-${unique}@example.test`, password: `Passw0rd!${prefix}` };
  const response = await request.post('/api/Users', {
    data: {
      email: customer.email,
      password: customer.password,
      passwordRepeat: customer.password,
      securityQuestion: { id: 1 },
      securityAnswer: 'test',
    },
  });
  expect(response.status(), await response.text()).toBe(201);
  return customer;
}

/** Shop REST API calls of one logged-in customer, used to prepare preconditions. */
export class ShopApi {
  private constructor(
    private readonly request: APIRequestContext,
    readonly session: Session,
  ) {}

  static async login(request: APIRequestContext, customer: Customer): Promise<ShopApi> {
    const response = await request.post('/rest/user/login', {
      data: { email: customer.email, password: customer.password },
    });
    expect(response.ok(), await response.text()).toBeTruthy();
    const { authentication } = await response.json();
    return new ShopApi(request, { token: authentication.token, basketId: authentication.bid });
  }

  private get headers() {
    return { Authorization: `Bearer ${this.session.token}` };
  }

  async addAddress(): Promise<number> {
    const response = await this.request.post('/api/Addresss', { headers: this.headers, data: ADDRESS });
    expect(response.ok(), await response.text()).toBeTruthy();
    return (await response.json()).data.id;
  }

  async addCard(): Promise<number> {
    const response = await this.request.post('/api/Cards', { headers: this.headers, data: CARD });
    expect(response.ok(), await response.text()).toBeTruthy();
    return (await response.json()).data.id;
  }

  async addToBasket(productId: number, quantity: number): Promise<void> {
    const response = await this.request.post('/api/BasketItems', {
      headers: this.headers,
      data: { ProductId: productId, BasketId: String(this.session.basketId), quantity },
    });
    expect(response.ok(), await response.text()).toBeTruthy();
  }

  /** Adds money to the wallet, paid with a saved card. Returns the new balance. */
  async topUpWallet(amount: number, cardId: number): Promise<number> {
    const response = await this.request.put('/rest/wallet/balance', {
      headers: this.headers,
      data: { balance: amount, paymentId: cardId },
    });
    expect(response.ok(), await response.text()).toBeTruthy();
    return (await response.json()).data;
  }

  async walletBalance(): Promise<number> {
    const response = await this.request.get('/rest/wallet/balance', { headers: this.headers });
    expect(response.ok(), await response.text()).toBeTruthy();
    return (await response.json()).data;
  }
}

